window.DV_TOPICS=window.DV_TOPICS||{};window.DV_TOPICS["online-shopping"]={"id":"online-shopping","order":4,"title_en":"Online Shopping Share","title_zh":"网购占比","blurb_zh":"线上零售份额怎么爬升","scene_zh":"一份全国零售样本（模拟数据）","views":[{"id":"share","type":"line","label_zh":"线上占比","label_en":"Online share","subject":"Online shopping's share of retail spending","subtitle_en":"Share of retail spending that happens online.","unit":{"en":"percent","short":"%","decimals":1,"kind":"percent","points":true},"data":{"x":{"label_en":"Year","label_zh":"年份","values":["2019","2020","2021","2022","2023","2024","2025","2026"]},"series":[{"id":"online","name_en":"Online","name_zh":"线上","slot":1,"values":[20.7,24.9,27.2,27.3,27.2,27.3,30.1,32.8]}]},"features":[{"kind":"rise_steady","marks":["seg:online:0","seg:online:1"],"slots":{"subject":"Online shopping's share of retail spending","unit":"%","category":"","period":"2019 to 2021","series_name":"Online","from":"20.7 percent","to":"27.2 percent","from_period":"2019","to_period":"2021","pct":"31","pp":"6.5","delta":"6.5 percentage points"},"auto":false,"id":"os-rise","examples":[{"en":"Online's share rose from 20.7 percent in 2019 to 27.2 percent in 2021.","zh":"线上份额从 2019 年的 20.7% 升到 2021 年的 27.2%。"}],"note_zh":"两年涨了 6.5 个百分点，用 rise 比 go up 更适合正式描述。","interpret_zh":"疫情推动了线上迁移，但这只是份额上升，不能说明线上消费总额同样增长。"},{"kind":"plateau","marks":["seg:online:2","seg:online:3","seg:online:4"],"slots":{"subject":"Online shopping's share of retail spending","unit":"%","category":"","period":"2021 to 2024","series_name":"Online","from":"27.2 percent","to":"27.3 percent","from_period":"2021","to_period":"2024","pct":"0.4","pp":"0.1","delta":"0.1 percentage points"},"auto":false,"id":"os-plateau","examples":[{"en":"The share stayed flat at around 27 percent from 2021 to 2024.","zh":"从 2021 到 2024 年，份额基本停在 27% 左右。"}],"note_zh":"连续几年几乎不动，用 level off / stay flat，不要用 grow slowly。","interpret_zh":"平台期说明线上迁移暂时停下，不是线上消费减少。"},{"kind":"turning_point","marks":["seg:online:5"],"slots":{"subject":"Online shopping's share of retail spending","unit":"%","category":"","period":"2024 to 2025","series_name":"Online","from":"27.3 percent","to":"30.1 percent","from_period":"2024","to_period":"2025","pct":"10","pp":"2.8","delta":"2.8 percentage points"},"auto":false,"id":"os-turn","examples":[{"en":"The flat stretch ended in 2025, when the share climbed to 30.1 percent.","zh":"2025 年这段平稳期结束，份额升到 30.1%。"}],"note_zh":"turning point 指方向改变的那一刻；这里是从持平转为上升。","interpret_zh":"转折点本身不解释原因，只标出变化开始的位置。"},{"kind":"rise_slight","marks":["seg:online:6"],"slots":{"subject":"Online shopping's share of retail spending","unit":"%","category":"","period":"2025 to 2026","series_name":"Online","from":"30.1 percent","to":"32.8 percent","from_period":"2025","to_period":"2026","pct":"9.0","pp":"2.7","delta":"2.7 percentage points"},"auto":false,"id":"os-last","examples":[{"en":"The share went up slightly in 2026, from 30.1 to 32.8 percent.","zh":"2026 年份额小幅上升，从 30.1% 到 32.8%。"}],"note_zh":"slightly 说幅度小；如果强调过程平缓，用 gradually。","interpret_zh":"最后一个区间的涨幅有限，不能据此推断会继续加速。"},{"kind":"trough","marks":["pt:online:0"],"slots":{"subject":"Online shopping's share of retail spending","unit":"%","category":"","period":"2019","series_name":"Online","value":"20.7 percent","peak":"32.8 percent","peak_period":"2026"},"auto":false,"id":"os-trough","examples":[{"en":"The series started at its low point: 20.7 percent in 2019.","zh":"序列从最低点开始：2019 年的 20.7%。"}],"note_zh":"trough 是周期里的最低点；起始点恰好最低时也可以这样描述。","interpret_zh":"这是样本起点，不是历史上真实的最低值。"},{"kind":"point","marks":["pt:online:1"],"slots":{"subject":"Online shopping's share of retail spending","unit":"%","category":"","period":"2020","series_name":"Online","value":"24.9 percent","peak":"32.8 percent","peak_period":"2026"},"auto":true},{"kind":"point","marks":["pt:online:2"],"slots":{"subject":"Online shopping's share of retail spending","unit":"%","category":"","period":"2021","series_name":"Online","value":"27.2 percent","peak":"32.8 percent","peak_period":"2026"},"auto":true},{"kind":"peak","marks":["pt:online:3"],"slots":{"subject":"Online shopping's share of retail spending","unit":"%","category":"","period":"2022","series_name":"Online","value":"27.3 percent","peak":"32.8 percent","peak_period":"2026"},"auto":true},{"kind":"trough","marks":["pt:online:4"],"slots":{"subject":"Online shopping's share of retail spending","unit":"%","category":"","period":"2023","series_name":"Online","value":"27.2 percent","peak":"32.8 percent","peak_period":"2026"},"auto":true},{"kind":"point","marks":["pt:online:5"],"slots":{"subject":"Online shopping's share of retail spending","unit":"%","category":"","period":"2024","series_name":"Online","value":"27.3 percent","peak":"32.8 percent","peak_period":"2026"},"auto":true},{"kind":"point","marks":["pt:online:6"],"slots":{"subject":"Online shopping's share of retail spending","unit":"%","category":"","period":"2025","series_name":"Online","value":"30.1 percent","peak":"32.8 percent","peak_period":"2026"},"auto":true},{"kind":"peak","marks":["pt:online:7"],"slots":{"subject":"Online shopping's share of retail spending","unit":"%","category":"","period":"2026","series_name":"Online","value":"32.8 percent","peak":"32.8 percent","peak_period":"2026"},"auto":false,"id":"os-peak","examples":[{"en":"The share reached its peak in 2026, at 32.8 percent.","zh":"份额在 2026 年达到峰值 32.8%。"}],"note_zh":"reach a peak / peak at + 数值，peak 前通常加 the。","interpret_zh":"图示范围内的最高点，不代表以后不会再高。"}],"overview_zh":"整体先快后停再回升：2019–2021 上升明显，2021–2024 基本持平，2025 年后恢复上升。占比上升不等于总支出上升。","descriptions":{"general":{"a2":"Online shopping's share of retail spending went up from about 21 percent in 2019 to about 33 percent in 2026. Most of the growth came early, and the share stayed flat for a few years before rising again.","b1":"The share climbed steadily from 20.7 percent in 2019 to 27.2 percent in 2021, then barely moved for three years. Growth returned in 2025 and 2026, taking the share to 32.8 percent.","b2":"Online shopping's share of retail spending rose by more than half over the period, from 20.7 to 32.8 percent. The increase was front-loaded: a 6.5-point gain by 2021 was followed by a plateau, before the share resumed its climb in 2025."},"ielts":"The proportion of retail spending made online rose from 20.7 percent in 2019 to 32.8 percent in 2026. The most marked increase occurred between 2019 and 2021, after which the figure leveled off for three years before rising again.","business":"Online's share of retail spending grew from 20.7 to 32.8 percent over seven years, but the growth was uneven. The 2021–2024 plateau suggests the channel shift paused rather than reversed; the 2025–2026 rebound is the signal to watch."}},{"id":"categories","type":"pie","label_zh":"品类构成","label_en":"Category mix","subject":"Online spending","subtitle_en":"How online spending splits across categories.","unit":{"en":"percent","short":"%","decimals":0,"kind":"percent","points":true},"data":{"parts":[{"id":"clothing","name_en":"Clothing","name_zh":"服装","slot":1,"value":31},{"id":"groceries","name_en":"Groceries","name_zh":"食品杂货","slot":2,"value":24},{"id":"home","name_en":"Home goods","name_zh":"家居","slot":3,"value":17},{"id":"electronics","name_en":"Electronics","name_zh":"电子产品","slot":4,"value":12},{"id":"beauty","name_en":"Beauty","name_zh":"美妆","slot":5,"value":9},{"id":"other","name_en":"Other","name_zh":"其他","slot":6,"value":7}]},"features":[{"kind":"largest_share","marks":["slice:clothing"],"slots":{"subject":"Online spending","category":"Clothing","share":"31 percent","share_number":"31","value":"31 percent","rank":"1"},"auto":false,"id":"osd-largest","examples":[{"en":"Clothing is the largest category, at 31 percent of online spending.","zh":"服装是最大品类，占网购支出的 31%。"}],"note_zh":"the largest share / category + at + 百分比。","interpret_zh":"31% 不到三分之一，不要写成 a third of。"},{"kind":"combined_share","marks":["slice:groceries"],"slots":{"subject":"Online spending","category":"Groceries","share":"24 percent","share_number":"24","value":"24 percent","rank":"2"},"auto":false,"id":"osd-combined","examples":[{"en":"Clothing and groceries together make up 55 percent of online spending.","zh":"服装和食品杂货合计占网购支出的 55%。"}],"note_zh":"together / combined + make up，注意主语是两项。","interpret_zh":"两项合计超过一半，说明品类集中度高。"},{"kind":"compare_shares","marks":["slice:home"],"slots":{"subject":"Online spending","category":"Home goods","share":"17 percent","share_number":"17","value":"17 percent","rank":"3"},"auto":false,"id":"osd-compare","examples":[{"en":"Home goods are 17 percent, roughly half the size of clothing.","zh":"家居占 17%，大约是服装的一半。"}],"note_zh":"用 half the size of / twice as large as 比较份额，不要只说 bigger。","interpret_zh":"比较时先确认基数：这里比的是份额，不是金额。"},{"kind":"item","marks":["slice:electronics"],"slots":{"subject":"Online spending","category":"Electronics","share":"12 percent","share_number":"12","value":"12 percent","rank":"4"},"auto":false,"id":"osd-electronics","examples":[{"en":"Electronics account for 12 percent of online spending.","zh":"电子产品占网购支出的 12%。"}],"note_zh":"account for + 百分比 是描述占比最稳的动词短语。","interpret_zh":"单项占比只能说明结构，不能说明增长。"},{"kind":"minority","marks":["slice:beauty"],"slots":{"subject":"Online spending","category":"Beauty","share":"9 percent","share_number":"9","value":"9 percent","rank":"5"},"auto":false,"id":"osd-minority","examples":[{"en":"Beauty is a small share, at just 9 percent.","zh":"美妆占比很小，只有 9%。"}],"note_zh":"minority 指少数份额；just 强调低于预期。","interpret_zh":"小份额也可能是高增长品类，这张图看不出增速。"},{"kind":"smallest_share","marks":["slice:other"],"slots":{"subject":"Online spending","category":"Other","share":"7 percent","share_number":"7","value":"7 percent","rank":"6"},"auto":false,"id":"osd-smallest","examples":[{"en":"Other categories make up the smallest slice, at 7 percent.","zh":"其他品类占比最小，为 7%。"}],"note_zh":"the smallest slice / share；slice 是饼图专有名词。","interpret_zh":"“Other”是一个合并项，不能拿它和单一品类直接比。"}],"overview_zh":"线上支出集中在服装和食品杂货，两项合计超过一半。各品类占比是结构信息，不能说明哪个品类增长最快。","descriptions":{"general":{"a2":"Clothing is the biggest category, at 31 percent of online spending. Groceries come next at 24 percent, and the other four categories make up the rest.","b1":"Clothing accounts for just under a third of online spending, with groceries second at 24 percent. Together, the two largest categories make up 55 percent of the total.","b2":"Online spending is concentrated in clothing and groceries, which account for 31 and 24 percent respectively. The remaining four categories each hold less than a fifth, with beauty and other items at 9 and 7 percent."},"ielts":"Clothing was the largest category of online spending at 31 percent, followed by groceries at 24 percent. The two categories together represented 55 percent of the total, while beauty and other items each accounted for under 10 percent.","business":"Clothing and groceries drive more than half of online spend. The long tail — electronics, beauty and other — is where basket-size experiments are likely to pay off."}}]};
